import sys
from collections import defaultdict

def count_optimal_paths(N, roads):
    graph = defaultdict(list)
    for u, v in roads:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node, parent):
        count = 0
        for neighbor in graph[node]:
            if neighbor != parent:
                count += dfs(neighbor, node)
        return count + 1

    total_paths = 0
    for node in range(1, N + 1):
        children = [dfs(child, node) for child in graph[node]]
        total_paths += sum(c * (N - c) for c in children)

    return total_paths // 2

def main():
    N = int(sys.stdin.readline())
    roads = [list(map(int, sys.stdin.readline().split())) for _ in range(N - 1)]
    result = count_optimal_paths(N, roads)
    print(result)

if __name__ == "__main__":
    main()

import sys
from collections import defaultdict, deque

def count_pokenom_paths(n, roads):
    graph = defaultdict(list)
    for u, v in roads:
        graph[u].append(v)
        graph[v].append(u)

    def bfs(start):
        visited = [-1] * (n + 1)
        queue = deque([(start, 0)])
        visited[start] = 0
        count = 0
        while queue:
            current, dist = queue.popleft()
            if dist == 2:
                count += 1
            elif dist < 2:
                for neighbor in graph[current]:
                    if visited[neighbor] == -1:
                        visited[neighbor] = dist + 1
                        queue.append((neighbor, dist + 1))
        return count

    total_paths = 0
    for node in range(1, n + 1):
        total_paths += bfs(node)

    # Each path is counted twice, once from each end
    return total_paths // 2

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    roads = [(int(data[i]), int(data[i + 1])) for i in range(1, 2 * (n - 1), 2)]

    result = count_pokenom_paths(n, roads)
    print(result)

if __name__ == "__main__":
    main()
